class GlobalFinancialData {
 final DateTime? from,to; final int revenue,collections,expenses,net,receivable,previousDebtCollected;
 final List<Map<String,Object?>> beneficiaries,partners;
 const GlobalFinancialData({required this.from,required this.to,required this.revenue,required this.collections,required this.expenses,required this.net,required this.receivable,required this.previousDebtCollected,required this.beneficiaries,required this.partners});
}
class GlobalFinancialReportService {
 final StationRepository repo; GlobalFinancialReportService(this.repo);
 static int netDistributable(int collections,int expenses)=>collections-expenses;
 static int totalReceivable(Iterable<int> balances)=>balances.fold<int>(0,(sum,b)=>sum+(b>0?b:0));
 static int estimatePreviousDebtCollected(Iterable<Map<String,int>> parties)=>parties.fold<int>(0,(sum,p)=>sum+(p['prior_debt']??0).clamp(0,p['period_collections']??0).toInt());
 int n(Object? x)=>(x is num?x:num.tryParse('$x')??0).round();
 String range(String col,DateTime? f,DateTime? t,List<Object?> a){final w=<String>[];if(f!=null){w.add('$col>=?');a.add(DateTime(f.year,f.month,f.day).toIso8601String());}if(t!=null){w.add('$col<?');a.add(DateTime(t.year,t.month,t.day+1).toIso8601String());}return w.isEmpty?'':' AND ${w.join(' AND ')}';}
 Future<GlobalFinancialData> load({DateTime? from,DateTime? to}) async {
 if(from!=null&&to!=null&&DateTime(from.year,from.month,from.day).isAfter(DateTime(to.year,to.month,to.day)))throw ArgumentError('الفترة غير صحيحة');
 final station=await repo.accounting.currentStationId();final cfg=await repo.settings();final endDate=to??DateTime.now();final end=DateTime(endDate.year,endDate.month,endDate.day+1).toIso8601String();
 final a=<Object?>[station];final rf=range('COALESCE(i.date,i.start_datetime)',from,to,a);final revenue=n((await repo.db.rawQuery("SELECT COALESCE(SUM(i.total_amount),0) v FROM irrigations i WHERE i.station_id=? AND i.status!='cancelled'$rf",a)).first['v']);
 final b=<Object?>[station];final pf=range('p.date',from,to,b);final collections=n((await repo.db.rawQuery("SELECT COALESCE(SUM(p.amount),0) v FROM payments p JOIN beneficiaries x ON x.id=p.beneficiary_id WHERE p.station_id=? AND p.status='posted'$pf",b)).first['v']);
 final c=<Object?>[station];final ef=range('e.date',from,to,c);final expenses=n((await repo.db.rawQuery("SELECT COALESCE(SUM(e.amount),0) v FROM expenses e WHERE e.station_id=? AND e.status='posted' AND e.partner_id IS NULL AND e.worker_id IS NULL$ef",c)).first['v']);
 final dieselCredit=cfg['diesel_delivery_financial_credit']=='true';
 String balance="b.opening_balance+b.carried_balance+COALESCE((SELECT SUM(md.amount) FROM beneficiary_manual_debts md WHERE md.beneficiary_id=b.id AND md.status='posted' AND md.date<?),0)+COALESCE((SELECT SUM(i.total_amount) FROM irrigations i WHERE i.station_id=b.station_id AND i.beneficiary_id=b.id AND i.status!='cancelled' AND COALESCE(i.date,i.start_datetime)<?),0)+COALESCE((SELECT SUM(d.amount) FROM diesel_movements d WHERE d.station_id=b.station_id AND d.beneficiary_id=b.id AND d.kind='advance' AND d.irrigation_id IS NULL AND d.date<?),0)-COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.station_id=b.station_id AND p.beneficiary_id=b.id AND p.status='posted' AND p.date<?),0)";
 if(dieselCredit)balance+="-COALESCE((SELECT SUM(d.amount) FROM diesel_movements d WHERE d.station_id=b.station_id AND d.beneficiary_id=b.id AND d.kind='delivery' AND d.date<?),0)";
 final q= dieselCredit?[end,end,end,end,end,station]:[end,end,end,end,station];
 final ben=await repo.db.rawQuery("SELECT b.id,b.name,COALESCE((SELECT SUM(i.total_amount) FROM irrigations i WHERE i.station_id=b.station_id AND i.beneficiary_id=b.id AND i.status!='cancelled' AND COALESCE(i.date,i.start_datetime)<?),0) irrigation_total,COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.station_id=b.station_id AND p.beneficiary_id=b.id AND p.status='posted' AND p.date<?),0) collections,($balance) closing_balance FROM beneficiaries b WHERE b.station_id=? AND b.status='active' ORDER BY b.name",[end,end,...q]);
 final due=totalReceivable(ben.map((row)=>n(row['closing_balance'])));int prior=0;if(from!=null){final endFilter=to==null?'':' AND p.date<?';final priorSql="SELECT COALESCE(SUM(MIN(MAX(b.opening_balance+b.carried_balance+COALESCE((SELECT SUM(md.amount) FROM beneficiary_manual_debts md WHERE md.beneficiary_id=b.id AND md.status='posted' AND md.date<?),0)+COALESCE((SELECT SUM(i.total_amount) FROM irrigations i WHERE i.station_id=b.station_id AND i.beneficiary_id=b.id AND i.status!='cancelled' AND COALESCE(i.date,i.start_datetime)<?),0)+COALESCE((SELECT SUM(d.amount) FROM diesel_movements d WHERE d.station_id=b.station_id AND d.beneficiary_id=b.id AND d.kind='advance' AND d.irrigation_id IS NULL AND d.date<?),0)-COALESCE((SELECT SUM(p0.amount) FROM payments p0 WHERE p0.station_id=b.station_id AND p0.beneficiary_id=b.id AND p0.status='posted' AND p0.date<?),0)${dieselCredit?"-COALESCE((SELECT SUM(dc.amount) FROM diesel_movements dc WHERE dc.station_id=b.station_id AND dc.beneficiary_id=b.id AND dc.kind='delivery' AND dc.date<?),0)":""},0),COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.station_id=b.station_id AND p.beneficiary_id=b.id AND p.status='posted' AND p.date>=?${endFilter}),0)),0) v FROM beneficiaries b WHERE b.station_id=?";final params=<Object?>[from.toIso8601String(),from.toIso8601String(),from.toIso8601String(),from.toIso8601String()];if(dieselCredit)params.add(from.toIso8601String());params.add(from.toIso8601String());if(to!=null)params.add(DateTime(to.year,to.month,to.day+1).toIso8601String());params.add(station);final row=(await repo.db.rawQuery(priorSql,params)).first['v'];prior=n(row).clamp(0,collections);}
 final ps=await repo.db.rawQuery("SELECT id,name,ownership_mode,ownership_percentage,shares_count FROM partners WHERE station_id=? AND active=1 ORDER BY name",[station]);final net=netDistributable(collections,expenses);final distributable=net>0?net:0;final allocations=AccountingCalculations.partnerDistributionAmounts(distributable:distributable,partners:ps);final partners=<Map<String,Object?>>[];for(final p in ps){final id=(p['id'] as num).toInt();final amount=allocations[id]??0;partners.add({...p,'weight':p['ownership_mode']=='percentage'?p['ownership_percentage']:p['shares_count'],'ratio':net>0?amount/net:0,'share_amount':amount});}
 return GlobalFinancialData(from:from,to:to,revenue:revenue,collections:collections,expenses:expenses,net:net,receivable:due,previousDebtCollected:prior,beneficiaries:ben,partners:partners);
 }
 Future<void> pdf(GlobalFinancialData d)async{
  final cfg=await repo.settings();final nf=NumberFormat('#,##0');String money(Object? x)=>nf.format(x is num?x:0);
  final period='الفترة: ${d.from==null?'من البداية':DateFormat('yyyy/MM/dd').format(d.from!)} إلى ${d.to==null?'حتى الآن':DateFormat('yyyy/MM/dd').format(d.to!)}';
  final boxes=[StatBoxData(number:'1',title:'إيراد السقايات',value:money(d.revenue)+' ريال'),StatBoxData(number:'2',title:'القبوضات الفعلية',value:money(d.collections)+' ريال'),StatBoxData(number:'3',title:'المصروفات',value:money(d.expenses)+' ريال'),StatBoxData(number:'4',title:d.net<0?'العجز بعد المصروفات':'الصافي القابل للتوزيع',value:money(d.net)+' ريال',isLarge:true,isBlueTint:true),StatBoxData(number:'5',title:'أرصدة المستفيدين عند نهاية الفترة',value:money(d.receivable)+' ريال'),StatBoxData(number:'6',title:'قبض ديون سابقة (تقديري)',value:money(d.previousDebtCollected)+' ريال')];
  final beneficiaryRows=d.beneficiaries.map((r)=>['${r['name']}',money(r['irrigation_total']),money(r['collections']),money(r['closing_balance'])]).toList();
  final partnerRows=d.partners.map((r)=>['${r['name']}','${r['ownership_mode']=='percentage'?'نسبة':'حصص'} • ${money(r['weight'])}',((r['ratio'] as num)*100).toStringAsFixed(2),money(r['share_amount'])]).toList();
  await OfficialReportTemplate.preview(rightHeader1:cfg['station_name']??'منظومة السقاية',rightHeader2:cfg['organization_name']??'الإدارة المالية',rightHeader3:'الجمهورية اليمنية',date:DateFormat('yyyy/MM/dd').format(DateTime.now()),refNumber:'GFR-${DateFormat('yyMMdd-HHmm').format(DateTime.now())}',attachments:period,reportTitle:'التقرير المالي العام للمنظومة',summaryBoxes:boxes,columns:['المستفيد','سقايات الفترة','القبوضات','الرصيد عند نهاية الفترة'],rows:beneficiaryRows,additionalSections:[OfficialReportTableSection(title:'حصص الشركاء المحسوبة — لا تعني صرفًا فعليًا',columns:['الشريك','أساس الملكية','نسبة الاستحقاق %','الحصة المحسوبة'],rows:partnerRows)],minTableRows:1,fileName:'التقرير المالي العام للمنظومة',thirdSignatureLabel:'اعتماد وختم المحطة: ....................');
 }
}
class GlobalFinancialReportPage extends StatefulWidget {final StationRepository repository;final DateTime? initialFrom,initialTo;const GlobalFinancialReportPage(this.repository,{this.initialFrom,this.initialTo,super.key});@override State<GlobalFinancialReportPage> createState()=>_GlobalFinancialReportPageState();}
class _GlobalFinancialReportPageState extends State<GlobalFinancialReportPage>{DateTime? from,to;GlobalFinancialData? data;bool loading=true;@override void initState(){super.initState();from=widget.initialFrom;to=widget.initialTo;load();}Future<void> load()async{setState(()=>loading=true);try{final v=await GlobalFinancialReportService(widget.repository).load(from:from,to:to);if(mounted)setState(()=>data=v);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر تحميل التقرير: $e')));}if(mounted)setState(()=>loading=false);}Future<void> pick(bool start)async{final v=await showDatePicker(context:context,initialDate:(start?from:to)??DateTime.now(),firstDate:DateTime(2000),lastDate:DateTime(2100));if(v==null)return;setState(()=>start?from=v:to=v);load();}String m(num n)=>NumberFormat('#,##0').format(n)+' ريال';Widget card(String label,num v)=>Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label),const SizedBox(height:5),Text(m(v),style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold))])));@override Widget build(BuildContext context){final d=data;return Scaffold(appBar:AppBar(title:const Text('التقرير المالي العام للمنظومة'),actions:[IconButton(onPressed:d==null?null:()=>GlobalFinancialReportService(widget.repository).pdf(d),icon:const Icon(Icons.picture_as_pdf))]),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(12),children:[Wrap(spacing:8,children:[OutlinedButton(onPressed:()=>pick(true),child:Text(from==null?'من البداية':DateFormat('yyyy/MM/dd').format(from!))),OutlinedButton(onPressed:()=>pick(false),child:Text(to==null?'حتى الآن':DateFormat('yyyy/MM/dd').format(to!))),TextButton(onPressed:(){setState((){from=null;to=null;});load();},child:const Text('كل الفترة'))]),if(d!=null)Wrap(spacing:8,runSpacing:8,children:[card('إيراد السقايات',d.revenue),card('القبوضات (تشمل الديون السابقة)',d.collections),card('مصروفات المحطة',d.expenses),card(d.net<0?'العجز':'الصافي القابل للتوزيع',d.net),card('أرصدة المستفيدين',d.receivable),card('قبض دين سابق (تقديري)',d.previousDebtCollected)]),const Text('المستفيدون',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),if(d!=null)...d.beneficiaries.map((r)=>ListTile(title:Text('${r['name']}'),subtitle:Text('السقايات: ${m((r['irrigation_total'] as num?)??0)} • القبوضات: ${m((r['collections'] as num?)??0)}'),trailing:Text(m((r['closing_balance'] as num?)??0)))),const Divider(),const Text('حصص الشركاء (حساب فقط — لا يسجل صرف)',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),if(d!=null)...d.partners.map((r)=>ListTile(title:Text('${r['name']}'),subtitle:Text('نسبة: ${((r['ratio'] as num)*100).toStringAsFixed(2)}%'),trailing:Text(m((r['share_amount'] as num?)??0))))])));}}